"use strict";(globalThis.webpackChunkmy_study_site=globalThis.webpackChunkmy_study_site||[]).push([[6899],{1897(e){e.exports=JSON.parse('{"categoryGeneratedIndex":{"title":"Inferential Statistics & Hypothesis Testing","description":"Inference is reasoning from a limited sample back to the population that generated it \u2014 and honestly quantifying how sure you\'re allowed to be. This module works one lecture at a time: the mindset (the null/alternative framing, the p-value, the two ways to be wrong), the tests for a mean (the z-test when \u03c3 is known, the Student-t distribution and t-test when it isn\'t, choosing between them, and the confidence interval), the categorical tests (chi-square goodness of fit), and Bayesian reasoning (Bayes\' theorem and the base-rate trap). Every page has an interactive lab or a visual and a runnable example. (Study reference: the \'Inferential Statistics\' section of a Complete Data Science bootcamp \u2014 all notes, code, and visuals are my own.)","slug":"/Statistics/inferential-statistics","permalink":"/docs/Statistics/inferential-statistics","sidebar":"tutorialSidebar","navigation":{"previous":{"title":"Correlation","permalink":"/docs/Statistics/descriptive-statistics/covariance-and-correlation/correlation"},"next":{"title":"1. The Testing Mindset","permalink":"/docs/category/1-the-testing-mindset"}}}}')}}]);